WITH unpivoted AS (SELECT id, category, metric_name, metric_value FROM (SELECT id, category, cost, price FROM products) src UNPIVOT (metric_value FOR metric_name IN (cost AS COST_VAL, price AS PRICE))) SELECT CASE WHEN metric_value >= 70 THEN 'HIGH' ELSE 'LOW' END AS metric_value_tier, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(metric_name)) AS metric_name_list, COUNT(CASE WHEN category = 'Fashion' THEN 1 END) AS fashion_count FROM unpivoted GROUP BY CUBE (CASE WHEN metric_value >= 70 THEN 'HIGH' ELSE 'LOW' END) HAVING fashion_count < 1000
